import { describe, it, expect } from 'vitest';
import { validateMessage } from './validation.js';

describe('list_sessions validation', () => {
  it('accepts a valid list_sessions message', () => {
    const message = { type: 'list_sessions', limit: 10 };
    const result = validateMessage(message);
    expect(result).toEqual({
      valid: true,
      data: { type: 'list_sessions', limit: 10 }
    });
  });

  it('rejects an invalid limit', () => {
    const message = { type: 'list_sessions', limit: 'ten' };
    const result = validateMessage(message);
    expect(result).toEqual({
      valid: false,
      error: 'Invalid limit: must be a non-negative integer'
    });
  });

  it('accepts a valid before cursor', () => {
    const message = {
      type: 'list_sessions',
      before: { updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1' }
    };
    const result = validateMessage(message);
    expect(result).toEqual({
      valid: true,
      data: {
        type: 'list_sessions',
        before: { updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1' }
      }
    });
  });
});

