  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  let limit: number | undefined;
  if ('limit' in message && message.limit !== undefined) {
    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0) {
      return {valid: false, error: 'Invalid limit: must be a non-negative integer'};
    }
    limit = message.limit;
  }

  let before: {updatedAt: string | number; sessionId: string} | undefined;
  if ('before' in message && message.before !== undefined) {
    if (typeof message.before !== 'object' || message.before === null) {
      return {valid: false, error: 'Invalid before: must be an object'};
    }
    const b = message.before as Record<string, unknown>;
    if (typeof b.sessionId !== 'string' || b.sessionId.length < 1 || b.sessionId.length > 128) {
      return {valid: false, error: 'Invalid before: sessionId must be 1-128 characters'};
    }
    if (typeof b.updatedAt !== 'string' && typeof b.updatedAt !== 'number') {
      return {valid: false, error: 'Invalid before: updatedAt must be a string or number'};
    }
    if (isNaN(new Date(b.updatedAt).getTime())) {
      return {valid: false, error: 'Invalid before: updatedAt must be a valid date'};
    }
    before = {updatedAt: b.updatedAt, sessionId: b.sessionId};
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(limit !== undefined ? {limit} : {}),
      ...(before !== undefined ? {before} : {}),
    },
  };
}

